{"packet_id": "D007-01", "doc_id": "D007", "jurisdiction": "CA", "category": "security_deposits", "lifecycle": "enacted", "title": "California security deposit cap under AB 12", "requirement": "Most landlords may demand at most one month's rent as security for furnished or unfurnished units; qualifying small landlords may demand up to two months' rent.", "key_value": "1 month's rent; 2 months' rent for qualifying small landlords", "coverage_conditions": "Residential rental units in California; last month's rent counts toward the deposit, first month's rent does not.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": true, "other": "two months allowed only for owners of two or fewer rental properties with no more than four residential units total, held by natural persons, family trusts or natural-person LLCs"}, "exemptions": null, "penalty": null, "effective_date": "2024-07-01", "citation": "Assembly Bill 12", "quoted_span": "Starting July 1, 2024, many landlords may only charge one month's rent for unfurnished and furnished units", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D007-01", "doc_id": "D007", "jurisdiction": "CA", "category": "security_deposits", "lifecycle": "enacted", "title": "California security deposit return and itemization", "requirement": "Within 21 days of the tenant leaving the unit vacant the landlord must return the remaining deposit with an itemized statement, copies of documents showing charges, and proof that repairs were completed.", "key_value": "21 days", "coverage_conditions": "Residential tenancies in California; applies to any portion of a security deposit that remains after permitted deductions.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "A landlord may deduct only amounts reasonably necessary for rent default, tenant-caused damage beyond wear and tear, cleaning, and lease-allowed replacement of personal property or furniture.", "penalty": null, "effective_date": null, "citation": "California state law, security deposit return and itemization", "quoted_span": "All or any remaining portion of a security deposit must be returned within 21 days after the tenant/s leave the unit vacant.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D007-01", "doc_id": "D007", "jurisdiction": "CA", "category": "security_deposits", "lifecycle": "enacted", "title": "California move-in photographs of the unit", "requirement": "For tenancies beginning on or after July 1, 2025, the landlord must photograph the unit immediately before or at the start of the tenancy to document its condition.", "key_value": null, "coverage_conditions": "Residential tenancies in California beginning on or after July 1, 2025.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": "2025-07-01", "citation": "California state law, photographs at start of tenancy", "quoted_span": "For tenancies that begin on or after July 1, 2025, a landlord must photograph the unit immediately before or at the start of a new tenancy to document the condition of the unit.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D007-01", "doc_id": "D007", "jurisdiction": "CA", "category": "security_deposits", "lifecycle": "enacted", "title": "California photographs before deposit deductions", "requirement": "From April 1, 2025 the landlord must photograph the unit after regaining possession but before repairs or cleaning, and give the photos and a written cost explanation with the itemized statement.", "key_value": null, "coverage_conditions": "Residential tenancies in California where the landlord intends to deduct for repairs or cleaning from the security deposit.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": "2025-04-01", "citation": "California state law, photographs after regaining possession", "quoted_span": "Starting April 1, 2025, landlords must take photographs of a unit after regaining possession, but before any repairs or cleaning for which the landlord intends to make a deduction from the security deposit.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D007-01", "doc_id": "D007", "jurisdiction": "Berkeley, CA", "category": "security_deposits", "lifecycle": "enacted", "title": "Berkeley security deposit interest", "requirement": "Landlords must pay tenants interest on the security deposit at the end of each year, plus a prorated amount if the tenant moves out before year end.", "key_value": null, "coverage_conditions": "Tenancies in units fully or partially covered by Berkeley's Rent Ordinance.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Berkeley Rent Ordinance, security deposit interest", "quoted_span": "For tenancies in units fully or partially covered by Berkeley's Rent Ordinance, landlords must pay tenants interest on their security deposit at the end of each year and a prorated amount if the tenant moves out before the end of the year.", "interaction": "Local interest duty adds to the state deposit cap.", "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
